// Change this line:
// const publishDate = $json.resultData?.publishDate;

// To this:
const publishDate = $('Fetch Recall Details').first().json.resultData?.publishDate;

// The rest of your code remains the same
let yearFull = null;
let yearYY = null;
let usedFallback = false;

if (publishDate && typeof publishDate === 'string' && publishDate.length >= 4) {
  try {
    const parsedYear = parseInt(publishDate.substring(0, 4), 10);
    if (!isNaN(parsedYear) && parsedYear > 1900 && parsedYear < 2100) {
      yearFull = parsedYear;
      yearYY = String(yearFull).slice(-2);
      // console.log(`Extracted year ${yearFull} (YY: ${yearYY}) from publishDate: ${publishDate}`);
    } else {
      // console.warn(`Parsed year (${parsedYear}) from publishDate "${publishDate}" seems invalid.`);
    }
  } catch (error) {
    // console.warn(`Error parsing year from publishDate "${publishDate}": ${error.message}`);
  }
}

if (yearFull === null || yearYY === null) {
  usedFallback = true;
  // console.warn(`publishDate ("${publishDate}") is missing or invalid. Using current KST date as fallback.`);
  try {
    const now = new Date();
    const formatter = new Intl.DateTimeFormat('en-US', {
      timeZone: 'Asia/Seoul',
      year: 'numeric',
    });
    const kstYearString = formatter.format(now);
    yearFull = parseInt(kstYearString, 10);
    yearYY = String(yearFull).slice(-2);
    // console.log(`Using fallback KST year: ${yearFull} (YY: ${yearYY})`);
  } catch (error) {
    console.error(`FATAL: Failed to get current KST year: ${error.message}`);
  }
}

if (yearFull === null || yearYY === null) {
  console.error("Unexpected error: Year could not be determined after fallback.");
}

return {
  "yearFull" : yearFull,
  "yearYY" : yearYY,
  "usedFallback": usedFallback
};

// HTML 엔티티 인코딩 함수 (매우 중요!)
function escapeXml(unsafe) {
  if (typeof unsafe !== 'string') {
    return unsafe === null || typeof unsafe === 'undefined' ? '' : String(unsafe);
  }
  return unsafe
       .replace(/&/g, "&")
       .replace(/</g, "<")
       .replace(/>/g, ">")
       .replace(/"/g, "\"")
       .replace(/'/g, "'");
}

// 입력 데이터 (Edit Fields 노드의 출력)
const data = $json;

// 이미지 태그 생성
let imageTags = '';
if (Array.isArray(data.imageFiles)) {
  data.imageFiles.forEach(img => {
    // imageFiles 배열의 각 요소가 {filename: '...'} 형태라고 가정
    if (img && img.filename) {
      imageTags += `
  <image>
    <data></data>
    <filename>${escapeXml(img.filename)}</filename>
    <media_type>image/jpeg</media_type>
    <alt_text></alt_text>
  </image>`;
    }
  });
}

// GPC 코드 태그 생성 (Brick 우선)
let gpcTags = '';
if (data.brickCode) {
  gpcTags = `<brick>${escapeXml(data.brickCode)}</brick>`;
} else {
  if (data.segmentCode) gpcTags += `<segment>${escapeXml(data.segmentCode)}</segment>`;
  if (data.familyCode) gpcTags += `<family>${escapeXml(data.familyCode)}</family>`;
  if (data.classCode) gpcTags += `<class>${escapeXml(data.classCode)}</class>`;
}

let manufacturer = '';
if (data.manufacturer) {
  manufacturer = `<manufacturer>${escapeXml(data.manufacturer)}</manufacturer>`;
} 

let manufacturerCountry = '';
if (data.manufacturerCountryCode) {
  manufacturerCountry = `<manufacturer_country_id>${escapeXml(data.manufacturerCountryCode)}</manufacturer_country_id>`;
} 

// 최종 XML 문자열 생성
const xmlString = `<?xml version="1.0" encoding="UTF-8"?>
<recall xmlns="urn:recall-schema" lang="en">
  <edit_type>${escapeXml(data.edit_type)}</edit_type>
  <id>${escapeXml(data.oecdId)}</id>
  <country_id>KR</country_id>
  ${manufacturerCountry}
  ${manufacturer}
  <product_type>${escapeXml(data.productType)}</product_type>
  <product_name>${escapeXml(data.productName)}</product_name>
  <product_desc>${escapeXml(data.productDesc)}</product_desc>
  <product_code>
    <publication>${"2024-05-01"}</publication>
    ${gpcTags}
  </product_code>
  <product_model_no>${escapeXml(data.modelNo)}</product_model_no>
  <hazard>${escapeXml(data.hazard)}</hazard>
  <injuries>${escapeXml(data.injuries)}</injuries>
  <action>${escapeXml(data.action)}</action>
  <units></units>
  <URL>${escapeXml(data.url)}</URL>
  <date>${data.publishDate}</date>
  ${imageTags}
  <manufacturer_website/>
</recall>`;

// 결과를 다음 노드로 전달 (입력 데이터에 xmlContent 추가)
return { ...data, xmlContent: xmlString };

const recallUid = $('Fetch Recall Info').item.json.resultData.recallUid;
const totalItemsInBatch = $input.all().length;

return $input.all().map((item, currentIndex) => {
  if (!item.json || typeof item.json !== 'object') {
    item.json = {};
  }
  let newFileSuffix;
  if (totalItemsInBatch >= 2) {
    if (currentIndex === 0) {
      newFileSuffix = '2';
    } else if (currentIndex === 1) {
      newFileSuffix = '1';
    } else {
      newFileSuffix = `${currentIndex + 1}`;
    }
  } else {
    newFileSuffix = `${currentIndex + 1}`;
  }
  item.json.imageFileNameSuffix = newFileSuffix;
  item.json.finalImageUrlForSupabase = `https://fczencruxulddednkint.supabase.co/storage/v1/object/product-images/${recallUid}${newFileSuffix}.jpg`;
  return item;
});
